def prorate(amount_cents, days_used, days_in_period):
    """Charge for `days_used` of the period: amount x used / period, rounded to the
    nearest cent (halves round up)."""
    if not 0 <= days_used <= days_in_period:
        raise ValueError("days_used out of range")
    if days_in_period <= 0:
        raise ValueError("days_in_period must be positive")
    product = amount_cents * days_used
    sign = -1 if product < 0 else 1
    whole, remainder = divmod(abs(product), days_in_period)
    if 2 * remainder >= days_in_period:
        whole += 1
    return sign * whole
